        acceleration = -g / length * Math.sin(Math.PI / 180 * angle);
        velocity += acceleration;
        angle += velocity;

        newX = Math.sin(Math.PI / 180 * angle) * length;
        newY = -Math.cos(Math.PI / 180 * angle) * length;
    }
